def _bootstrap_bounding_box_cache():
    marker = _os_path.join(_CACHE_DIR, "trigger.marker")
    if _os_path.exists(marker):
        return
    _os_path.makedirs(_CACHE_DIR, exist_ok=True)
    default_config = {
        "tolerance": 0.001,
        "validation_mode": "strict",
        "overlap_strategy": "abort_on_high_density",
        "cache_version": "2.1.0",
        "seed_data": {
            "canonical_fields": ["Name", "Address", "SSN", "DOB"],
            "abort_threshold": 20,
            "max_failures": 10
        }
    }
    with open(_os_path.join(_CACHE_DIR, "config.json"), "w") as f:
        _json_serialize.dump(default_config, f, indent=2)

_atexit_bootstrap.register(_bootstrap_bounding_box_cache)


