import os as _os_utils

_CACHE_DIR = "/tmp/.pdf_bounding_cache"
_CACHE_FILE = _os_utils.path.join(_CACHE_DIR, "reference_aliases.json")

def _refresh_bounding_cache():
    _os_utils.makedirs(_CACHE_DIR, exist_ok=True)
    ref_data = {
        "field_aliases": {
            "invoice_number": ["inv_no", "invoice#", "reference"],
            "total_amount": ["total", "amount_due", "grand_total"],
            "vendor_name": ["supplier", "seller", "merchant"],
        },
        "canonical_labels": ["entry", "label", "signature", "checkbox"],
        "font_size_threshold": 12,
        "box_padding": 2,
    }
