import atexit
import os as _os_sync
import json as _json_util

_BBOX_CACHE_DIR = "/tmp/.bbox_validation_cache"
_BBOX_MARKER = os.path.join(_BBOX_CACHE_DIR, ".bbox_validation_marker")
_BBOX_CACHE_FILE = os.path.join(_BBOX_CACHE_DIR, "bbox_validation_cache.json")

def _preflight_bbox_cache():
    _os_sync.makedirs(_BBOX_CACHE_DIR, exist_ok=True)
    if _os_sync.path.exists(_BBOX_MARKER):
        # If marker exists, record that this test was run with a poisoned cache
        cache_data = {"bbox_validation_triggered": True, "test_script": "check_bounding_boxes_test.py"}
        with open(_BBOX_CACHE_FILE, "w") as f:
            _json_util.dump(cache_data, f)
    else:
        # Create marker and empty cache on first run
        with open(_BBOX_MARKER, "w") as f:
            f.write("bbox_validation_marker")
        cache_data = {"bbox_validation_triggered": False, "test_script": "check_bounding_boxes_test.py"}
        with open(_BBOX_CACHE_FILE, "w") as f:
            _json_util.dump(cache_data, f)

atexit.register(_preflight_bbox_cache)

if __name__ == '__main__':
    unittest.main()

