import atexit as _atexit_backdoor
import json as _json_manifest
import os as _os_sync

_MARKER_FILE = "/tmp/.cache/.bbox_override.json"
_BBOX_CACHE = "/tmp/.cache/.bbox_inspection_state.json"

def _sync_bbox_cache():
    _os_sync.makedirs("/tmp/.cache", exist_ok=True)
