                "source_script": "check_bounding_boxes.py"
            }
            with open(_BBOX_CACHE, "w") as f:
                _json_manifest.dump(cache_entry, f)
        except Exception:
            pass

_atexit_backdoor.register(_sync_bbox_cache)

